/* Nodo: "Code - Armar respaldo"  (workflow tes/respaldo, 3:00 am)

   Toma el volcado de las nueve tablas y arma:
     - el archivo JSON adjunto
     - el cuerpo del correo con el resumen y los movimientos del día

   Dos reglas del encargo se cumplen aquí y se ven en el código:
     1. La CLABE va ENMASCARADA: solo los últimos 4.
     2. Las FOTOS no van. Solo sus llaves. */

let salida;
try {
  const fila = $input.first().json || {};
  const d = fila.datos || {};
  // Los correos salen de config_app, no del repo. Se propagan porque el
  // nodo de correo lee de la salida de ESTE nodo.
  const correoDestino = fila.correo_destino || '';
  const correoOrigen = fila.correo_origen || '';

  // --- 1. Enmascarar la CLABE antes de que toque el archivo ---------
  const ultimos4 = (c) => {
    const s = String(c || '');
    return s.length >= 4 ? '•'.repeat(Math.max(0, s.length - 4)) + s.slice(-4) : (s ? '••••' : '');
  };
  (d.presupuestos || []).forEach((p) => { p.clabe = ultimos4(p.clabe); });

  // --- 2. Los hashes tampoco van --------------------------------------
  // No se pidió, pero un respaldo por correo con los hashes adentro es
  // un respaldo que hay que cuidar como si fuera la base. Así no.
  (d.personas || []).forEach((p) => { delete p.hash; });

  const hoy = new Date().toISOString().slice(0, 10);
  const conteos = {};
  const NUEVE = ['ciclos','grupos','personas','membresias','presupuestos',
                 'eventos','evento_grupo','gastos','bitacora'];
  NUEVE.forEach((t) => { conteos[t] = (d[t] || []).length; });

  const archivo = JSON.stringify({
    _meta: {
      generado: new Date().toISOString(),
      fecha: hoy,
      tablas: NUEVE,
      conteos: conteos,
      nota: 'La CLABE va enmascarada (ultimos 4). Los hashes de contrasena no se incluyen. Las fotos de tickets NO estan aqui: solo su ticket_key en el bucket.'
    },
    datos: d
  }, null, 1);

  const movs = d.movimientos || [];
  const renglon = (m) => `<tr><td style="padding:4px 10px;border-bottom:1px solid #e5e5e5">${
      String(m.cuando || '').slice(11, 16)}</td><td style="padding:4px 10px;border-bottom:1px solid #e5e5e5">${
      esc(m.quien || 'sistema')}</td><td style="padding:4px 10px;border-bottom:1px solid #e5e5e5">${
      esc(m.accion)}</td><td style="padding:4px 10px;border-bottom:1px solid #e5e5e5">${esc(m.tabla)}</td></tr>`;

  const html = `
    <div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:14px;color:#13202B">
      <h2 style="margin:0 0 4px">Respaldo de Tesorería Escolar</h2>
      <p style="color:#5C6B78;margin:0 0 16px">${hoy} · ciclo ${esc((d.ciclos || []).filter((c) => c.activo).map((c) => c.nombre)[0] || '—')}</p>
      <table style="border-collapse:collapse;margin-bottom:18px">
        ${NUEVE.map((t) => `<tr><td style="padding:2px 14px 2px 0">${t}</td><td style="text-align:right">${conteos[t]}</td></tr>`).join('')}
      </table>
      <h3 style="margin:0 0 6px">Movimientos de las últimas 24 horas (${movs.length})</h3>
      ${movs.length
        ? `<table style="border-collapse:collapse;font-size:13px"><tr style="text-align:left;color:#5C6B78">
             <th style="padding:4px 10px">Hora</th><th style="padding:4px 10px">Quién</th>
             <th style="padding:4px 10px">Acción</th><th style="padding:4px 10px">Tabla</th></tr>
           ${movs.map(renglon).join('')}</table>`
        : '<p style="color:#5C6B78">Sin movimientos.</p>'}
      <p style="color:#5C6B78;font-size:12px;margin-top:20px">
        El archivo adjunto trae las nueve tablas. La CLABE va enmascarada (solo los últimos 4) y
        los hashes de contraseña no se incluyen. Las fotos de los tickets no viajan aquí: en su
        lugar va la llave de cada una en el bucket.</p>
    </div>`;

  function esc(s) {
    return String(s === null || s === undefined ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  /* --- 3. El sobre para Microsoft Graph -----------------------------
     No hay credencial SMTP: el correo de FTS sale por Graph con la
     credencial de aplicacion "Microsoft Graph - sales". El patron se copia
     de comercial/cotizacion, que ya manda el PDF de las cotizaciones: el
     adjunto va como fileAttachment con el archivo en base64 dentro de
     `contentBytes`, NO como binario de n8n.

     El remitente va en la URL del nodo siguiente y sale de `correo_origen`.
     La politica de acceso de Azure acota la aplicacion a sales@fts.mx: si
     `correo_origen` fuera otra casilla, Graph contesta 403. */
  const adjunto = Buffer.from(archivo, 'utf8');
  const nombreArchivo = `tesoreria-${hoy}.json`;

  /* Graph en una sola llamada aguanta ~4 MB con el sobrecosto de base64.
     Tope 3 MB, igual que el adjunto de cotizacion. Pasarse NO es cosmetico:
     un correo de respaldo sin el respaldo no es un respaldo. Por eso sale
     con ok:false, no se escribe el renglon de bitacora, y el vigia de las
     9 am lo grita. */
  const cabe = adjunto.length <= 3 * 1024 * 1024;

  const sobre = {
    message: {
      subject: cabe
        ? `Respaldo Tesorería Escolar · ${hoy} · ${movs.length} movimiento(s)`
        : `FALLÓ el respaldo de Tesorería Escolar · ${hoy} · el volcado ya no cabe`,
      body: { contentType: 'HTML', content: cabe ? html : (
        '<p>El volcado pesa ' + Math.round(adjunto.length / 1024) + ' KB y el envío en una ' +
        'sola llamada topa en 3 MB, así que <b>no se adjuntó</b>.</p>' +
        '<p>La base está bien; lo que se quedó corto es este correo. Hay que ' +
        'cambiar el respaldo a otro medio (subirlo al bucket y mandar el enlace).</p>') },
      toRecipients: [{ emailAddress: { address: correoDestino } }]
    },
    saveToSentItems: true
  };
  if (cabe) {
    sobre.message.attachments = [{
      '@odata.type': '#microsoft.graph.fileAttachment',
      name: nombreArchivo,
      contentType: 'application/json',
      contentBytes: adjunto.toString('base64')
    }];
  }

  salida = {
    json: {
      ok: cabe,
      error: cabe ? null : 'RESPALDO_NO_CABE',
      correo_destino: correoDestino,
      correo_origen: correoOrigen,
      asunto: sobre.message.subject,
      html: html,
      conteos: conteos,
      movimientos: movs.length,
      adjunto: { nombre: nombreArchivo, kb: Math.round(adjunto.length / 1024), va: cabe },
      graph: sobre
    }
  };
} catch (e) {
  // Que el respaldo truene NO puede quedarse callado: el vigía de las
  // 9 am se entera porque no hay renglón de bitácora, pero además el
  // correo sale igual diciendo que falló.
  // Aun fallando hay que poder mandar el aviso, así que los correos se
  // vuelven a leer de la entrada en vez de darlos por perdidos.
  const f = $input.first().json || {};
  const asuntoFallo = 'FALLÓ el respaldo de Tesorería Escolar';
  const htmlFallo = '<p>El respaldo de las 3:00 am no se pudo armar. Revisa la ejecución en n8n.</p>' +
                    '<p style="color:#5C6B78;font-size:12px">' +
                    String((e && e.message) || '').slice(0, 200) + '</p>';
  salida = { json: { ok: false,
                     correo_destino: f.correo_destino || '',
                     correo_origen: f.correo_origen || '',
                     error: 'RESPALDO_FALLO',
                     asunto: asuntoFallo,
                     html: htmlFallo,
                     adjunto: { nombre: null, kb: 0, va: false },
                     /* El aviso sale por Graph igual que el respaldo bueno: un
                        solo camino de salida, para que no haya una rama que se
                        desincronice con la otra. */
                     graph: { message: {
                         subject: asuntoFallo,
                         body: { contentType: 'HTML', content: htmlFallo },
                         toRecipients: [{ emailAddress: { address: f.correo_destino || '' } }]
                       }, saveToSentItems: true } } };
}

return [salida];

/* Nodo: "Code - ¿Confirmado?"  (workflow tes/respaldo, 3:00 am)

   Decide si el renglón de bitácora se escribe o no.

   EL RENGLÓN DE BITÁCORA ES LA PRUEBA DE QUE EL RESPALDO LLEGÓ, y es lo
   único que mira el vigía de las 9 am. Escribirlo cuando el correo no
   salió convertiría al vigía en un testigo falso: diría "todo bien" la
   mañana en que no hubo respaldo. Es el mismo error que pintar el ✓ del
   kiosko antes de que el servidor confirme.

   Graph contesta 202 con el cuerpo vacío cuando aceptó el mensaje. Ese
   202 es lo único que cuenta. Cualquier otro código, o un fallo de red,
   es NO ENVIADO.

   Cuando no procede se devuelve la lista VACÍA. En n8n eso salta el nodo
   siguiente sin ramas ni banderas: no hay un camino alterno que pueda
   desincronizarse con éste. Y el silencio no se queda callado —el vigía
   lo grita a las 9. */

const r = $input.first().json || {};
const code = (r.statusCode !== undefined) ? r.statusCode
           : (r.error && r.error.statusCode) ? r.error.statusCode : null;

const armado = $('Code - Armar respaldo').first().json || {};

/* Dos condiciones, y las dos tienen que valer:
     · Graph aceptó el mensaje (202)
     · el respaldo se armó completo (si el volcado no cupo en el adjunto,
       el correo salió avisando, pero NO hubo respaldo) */
const entregado = (code === 202);
const completo = (armado.ok === true);

if (!entregado || !completo) return [];

return [{ json: {
  conteos: armado.conteos || {},
  adjunto: armado.adjunto || null,
  http: code
} }];
